// lib/segment/src/types.rs line 3857-3865
/// All conditions must NOT match
#[validate(nested)]
#[serde(
    default,
    with = "MaybeOneOrMany",
    skip_serializing_if = "Option::is_none"
)]
#[schemars(with = "MaybeOneOrMany<Condition>")]
pub must_not: Option<Vec<Condition>>,

// lib/segment/src/index/query_optimization/optimized_filter.rs line 75-81
fn check_must_not(must_not: &Option<Vec<OptimizedCondition>>, point_id: PointOffsetType) -> bool {
    let check = |condition| !check_condition(condition, point_id);
    match must_not {
        None => true,
        Some(conditions) => conditions.iter().all(check),
    }
}
